import numpy as np


def class_probabilities(y: np.ndarray) -> np.ndarray:
    """লেবেল অ্যারে y থেকে প্রতিটি বিদ্যমান ক্লাসের empirical probability vector বের করে।"""
    y_arr = np.asarray(y).reshape(-1)
    if y_arr.size == 0:
        return np.empty(0, dtype=np.float64)
    _, counts = np.unique(y_arr, return_counts=True)
    return counts.astype(np.float64) / y_arr.size


def gini_impurity(y: np.ndarray) -> float:
    """Gini Impurity: 1 - sum(p_k^2)."""
    probs = class_probabilities(y)
    if probs.size == 0:
        return 0.0
    return float(1.0 - np.sum(probs ** 2))


def entropy_impurity(y: np.ndarray) -> float:
    """Shannon Entropy (bits): -sum(p_k * log2(p_k)) for p_k > 0."""
    probs = class_probabilities(y)
    probs = probs[probs > 0.0]
    if probs.size == 0:
        return 0.0
    return float(-np.sum(probs * np.log2(probs)))


