class SplitEvaluator:
    """কোনো একক ফিচার কলামের সম্ভাব্য threshold গুলোকে Information Gain দিয়ে র‍্যাঙ্ক করে।"""

    def __init__(self, criterion: str = "gini") -> None:
        self.criterion = criterion

    def score_threshold(
        self, x_col: np.ndarray, y: np.ndarray, threshold: float
    ) -> float:
        x_arr = np.asarray(x_col, dtype=np.float64).reshape(-1)
        y_arr = np.asarray(y).reshape(-1)
        mask = x_arr <= threshold
        return information_gain(y_arr, y_arr[mask], y_arr[~mask], self.criterion)

    def best_threshold(
        self, x_col: np.ndarray, y: np.ndarray, candidates: list[float]
    ) -> tuple[float | None, float]:
        best_thr, best_gain = None, 0.0
        for thr in candidates:
            gain = self.score_threshold(x_col, y, thr)
            if gain > best_gain:
                best_gain = gain
                best_thr = float(thr)
        return best_thr, best_gain

from dataclasses import dataclass
import numpy as np


@dataclass
class TreeNode:
    feature: int | None = None
    threshold: float | None = None
    left: "TreeNode | None" = None
    right: "TreeNode | None" = None
    value: int | None = None


def gini_from_counts(counts: np.ndarray, total: int) -> float:
    """ক্লাস কাউন্ট অ্যারে থেকে O(K) সময়ে Gini Impurity হিসাব করে।"""
    if total <= 0:
        return 0.0
    probs = counts / float(total)
    return float(1.0 - np.sum(probs * probs))


class DecisionTreeClassifier:
    """CART Gini-based Decision Tree Classifier।"""

    def __init__(self, max_depth: int = 5, min_samples_leaf: int = 1) -> None:
        self.max_depth = int(max_depth)
        self.min_samples_leaf = int(min_samples_leaf)
        self.root_: TreeNode | None = None

    def find_best_split(
        self, X: np.ndarray, y: np.ndarray
    ) -> tuple[int | None, float | None, float]:
        """
        সব ফিচার ও sorted midpoint threshold খুঁজে সর্বোচ্চ Gini Information Gain দেওয়া split বের করে।

        Args:
            X: Feature matrix at current node, shape (N, D).
            y: Class labels at current node, shape (N,).

        Returns:
            (best_feature, best_threshold, best_gain).
            কোনো বৈধ positive-gain split না থাকলে (None, None, 0.0).
        """
        # TODO: Implement O(D N log N) sorted-midpoint split search with
        # incremental left/right class counts, strict tie skipping (x[i] == x[i+1]),
        # এবং min_samples_leaf enforcement.
        raise NotImplementedError("Implement find_best_split")

    def _majority_class(self, y: np.ndarray) -> int:
        classes, counts = np.unique(y, return_counts=True)
        return int(classes[int(np.argmax(counts))])

    def _build(self, X: np.ndarray, y: np.ndarray, depth: int) -> TreeNode:
        if depth >= self.max_depth or np.unique(y).size <= 1:
            return TreeNode(value=self._majority_class(y))
        feat, thr, gain = self.find_best_split(X, y)
        if feat is None or thr is None or gain <= 0.0:
            return TreeNode(value=self._majority_class(y))
        left_mask = X[:, feat] <= thr
        return TreeNode(
            feature=feat,
            threshold=thr,
            left=self._build(X[left_mask], y[left_mask], depth + 1),
            right=self._build(X[~left_mask], y[~left_mask], depth + 1),
        )

    def fit(self, X: np.ndarray, y: np.ndarray) -> "DecisionTreeClassifier":
        X_arr = np.asarray(X, dtype=np.float64)
        y_arr = np.asarray(y, dtype=int).reshape(-1)
        self.root_ = self._build(X_arr, y_arr, depth=0)
        return self

    def _predict_one(self, x: np.ndarray, node: TreeNode) -> int:
        while node.value is None:
            assert node.feature is not None and node.threshold is not None
            node = node.left if x[node.feature] <= node.threshold else node.right  # type: ignore[assignment]
        return node.value

    def predict(self, X: np.ndarray) -> np.ndarray:
        if self.root_ is None:
            raise RuntimeError("Fit the tree before calling predict.")
        X_arr = np.asarray(X, dtype=np.float64)
        return np.array([self._predict_one(row, self.root_) for row in X_arr], dtype=int)

from collections import deque
import numpy as np


class DBSCAN:
    """Density-Based Spatial Clustering of Applications with Noise (DBSCAN)।"""

    UNVISITED: int = -2
    NOISE: int = -1

    def __init__(self, eps: float = 0.5, min_samples: int = 5) -> None:
        if eps <= 0.0:
            raise ValueError("eps must be strictly positive.")
        if min_samples < 1:
            raise ValueError("min_samples must be at least 1.")
        self.eps = float(eps)
        self.min_samples = int(min_samples)

    @staticmethod
    def _pairwise_distances(X: np.ndarray) -> np.ndarray:
        sq = np.sum(X * X, axis=1, keepdims=True)
        sq_dists = np.maximum(sq + sq.T - 2.0 * (X @ X.T), 0.0)
        return np.sqrt(sq_dists)

    def _region_query(self, dist_matrix: np.ndarray, idx: int) -> list[int]:
        """idx বিন্দুর <= eps দূরত্বের সব প্রতিবেশীর ইনডেক্স (নিজেকেসহ) রিটার্ন করে।"""
        return np.flatnonzero(dist_matrix[idx] <= self.eps).tolist()

    def expand_cluster(
        self,
        dist_matrix: np.ndarray,
        labels: np.ndarray,
        seed_idx: int,
        neighbors: list[int],
        cluster_id: int,
    ) -> None:
        """
        একটি Core Point (seed_idx) থেকে BFS চালিয়ে density-reachable পুরো ক্লাস্টার প্রসারিত করে।

        Args:
            dist_matrix: Pairwise Euclidean distance matrix, shape (N, N).
            labels: Mutable 1D int array of cluster labels (UNVISITED=-2, NOISE=-1, or >=0).
            seed_idx: Core point index starting this cluster.
            neighbors: seed_idx-এর eps-neighborhood indices.
            cluster_id: বর্তমান ক্লাস্টারের অ-ঋণাত্মক আইডি (0, 1, 2, ...).
        """
        # TODO: Assign seed_idx to cluster_id, initialize BFS deque + in_queue set,
        # rescue NOISE border points into cluster_id, এবং প্রতিটি UNVISITED core point-এর
        # প্রতিবেশীদের কিউতে যোগ করে ক্লাস্টার প্রসারিত করুন।
        raise NotImplementedError("Implement expand_cluster")

    def fit_predict(self, X: np.ndarray) -> np.ndarray:
        X_arr = np.asarray(X, dtype=np.float64)
        n_samples = X_arr.shape[0]
        if n_samples == 0:
            return np.empty(0, dtype=int)

        dist_matrix = self._pairwise_distances(X_arr)
        labels = np.full(n_samples, self.UNVISITED, dtype=int)
        cluster_id = 0

        for i in range(n_samples):
            if labels[i] != self.UNVISITED:
                continue
            neighbors = self._region_query(dist_matrix, i)
            if len(neighbors) < self.min_samples:
                labels[i] = self.NOISE
            else:
                self.expand_cluster(dist_matrix, labels, i, neighbors, cluster_id)
                cluster_id += 1

        return labels
